#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // &n 取出 n 的地址，p 这个变量里存的就是这个地址
    int* p = &n;

    // *p 表示「p 指向的那个变量」，也就是 n 本身，
    // 所以改 *p 就等于改 n
    *p = *p * 2;

    cout << n << endl;
    return 0;
}

