#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 引用必须在声明时绑定到某个变量，之后不能再改绑到别的变量
    int& r = n;

    // r 就是 n 的另一个名字，改 r 就是改 n
    r = r * 3;

    // 这里是拷贝：copy 是独立的一份，和 n 没有关系
    int copy = n;
    copy = copy - 1;

    cout << n << endl;
    cout << copy << endl;
    return 0;
}

