#include <iostream>
using namespace std;

// 参数是指针：x、y 里存的是外面 a、b 的地址
void swapByPtr(int* x, int* y) {
    int t = *x;   // 把 x 指向的值先存起来
    *x = *y;      // 把 y 指向的值写进 x 指向的那个变量
    *y = t;
}

int main() {
    int a, b;
    cin >> a >> b;

    // 传的是地址而不是值：只传值的话，函数改的是自己的副本，外面看不到变化
    swapByPtr(&a, &b);

    cout << a << endl;
    cout << b << endl;
    return 0;
}

