#include <iostream>
using namespace std;

// 引用参数：x 是调用者那个变量的别名，不是拷贝
void swapByRef(int& x, int& y) {
    int t = x;
    x = y;   // 改 x 就是改外面的那个变量
    y = t;
}

int main() {
    int a, b;
    cin >> a >> b;

    // 引用参数直接传变量名，不用写 &，也不用解引用
    swapByRef(a, b);

    cout << a << endl;
    cout << b << endl;
    return 0;
}

