#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int arr[100];
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    // 数组名 arr 就是首元素的地址，所以可以直接用指针接住
    int* p = arr;

    // 正序：*(p + i) 与 p[i]、arr[i] 完全等价
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << *(p + i);
    }
    cout << endl;

    // 倒序：第 i 个要取的是倒数第 i+1 个元素，下标是 n-1-i
    // 写成 n-i 就越界了，会读到数组外面的垃圾值
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << *(p + n - 1 - i);
    }
    cout << endl;
    return 0;
}

