#include <iostream>
#include <iomanip>
using namespace std;

// p 是数组首元素的地址；const 表示函数不会通过 p 修改数组里的元素
// sum / mn / mx 是引用参数：函数里改它们，就是改调用者的变量
void analyze(const int* p, int n, int& sum, int& mn, int& mx) {
    sum = 0;

    // 用第一个元素初始化最值。
    // 如果初始化成 0，遇到全是负数的数组就会得到错误的「最大值 0」
    mn = *(p + 0);
    mx = *(p + 0);

    // 用指针遍历：*(p + i) 等价于 p[i]
    for (int i = 0; i < n; i++) {
        int v = *(p + i);
        sum += v;
        if (v < mn) mn = v;
        if (v > mx) mx = v;
    }
}

int main() {
    int n;
    cin >> n;

    int arr[100];
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    int sum = 0, mn = 0, mx = 0;
    // 数组名 arr 是首元素地址，正好对上参数 const int*
    // 后三个参数传变量名即可，函数会直接写进它们里面
    analyze(arr, n, sum, mn, mx);

    cout << sum << endl;
    cout << mn << endl;
    cout << mx << endl;

    // 一定要写 1.0：写成 sum / n 会做整数除法，3 / 4 得到 0
    double avg = sum * 1.0 / n;
    cout << fixed << setprecision(2) << avg << endl;
    return 0;
}

